const fs = require('fs');
const RAIZ = 'C:\\Users\\usuario\\Desktop\\Projeto-professor-William';
const ALERTAS = RAIZ + '\\auditoria\\alertas-automaticos.md';

const hoje = new Date();
const pad = n => String(n).padStart(2, '0');
const hojeStr = `${hoje.getFullYear()}-${pad(hoje.getMonth()+1)}-${pad(hoje.getDate())}`;
const DIGEST = `${RAIZ}\\pesquisa-diaria\\${hojeStr}.md`;

const ESPERADAS = ['A','B','C','D','E','F','G','H','I','J','K','L','M','N','O','P'];

let bloco = `\n## ${hojeStr} ${pad(hoje.getHours())}:${pad(hoje.getMinutes())} — n8n (automático, Trilhas Incompletas)\n\n`;

if (!fs.existsSync(DIGEST)) {
  bloco += `Digest de hoje (${hojeStr}) ainda não existe em pesquisa-diaria/ — nenhuma trilha rodou ainda.\n`;
} else {
  const content = fs.readFileSync(DIGEST, 'utf8');
  const faltando = ESPERADAS.filter(letra => {
    const re = new RegExp('Trilha ' + letra + '(\\b|\\s|$)');
    return !re.test(content);
  });
  if (faltando.length === 0) {
    bloco += `Todas as ${ESPERADAS.length} trilhas (A-P) têm entrada real hoje. Cobertura completa.\n`;
  } else {
    bloco += `${faltando.length} de ${ESPERADAS.length} trilhas SEM entrada hoje: ${faltando.join(', ')}.\n`;
  }
}

if (!fs.existsSync(ALERTAS)) {
  fs.writeFileSync(ALERTAS, '# Alertas automáticos — n8n\n\nLido pelo Diretor no início de toda sessão, junto com o resto de auditoria/.\n' + bloco, 'utf8');
} else {
  fs.appendFileSync(ALERTAS, bloco, 'utf8');
}

return [{ json: { digestExiste: fs.existsSync(DIGEST) } }];
